describe('Confirmation Modal Before Deletion', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display confirmation modal when user attempts to delete a record', () => {
    // Get the delete button for the first record
    cy.get('[data-testid="record-delete-btn-1"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    // Verify record is deleted
    cy.get('[data-testid="record-1"]').should('not.exist');
    cy.get('[data-testid="confirmation-modal"]').should('not.exist');
  });

  it('should not display confirmation modal when record is already deleted', () => {
    // Delete the first record
    cy.get('[data-testid="record-delete-btn-1"]').click();
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();
    cy.get('[data-testid="record-1"]').should('not.exist');

    // Attempt to delete a non-existent record
    cy.get('[data-testid="record-delete-btn-2"]').click();

    // Verify confirmation modal does not appear
    cy.get('[data-testid="confirmation-modal"]').should('not.exist');
    cy.get('[data-testid="confirm-delete-btn"]').should('not.be.visible');
  });
});
